import { z } from "zod";
import { decimal, type Curriculum } from "./schema";

// Course master: every course in the four 情報学部 curriculum tables, one entry
// per (department, course). Generated by scripts/build-course-master.mjs.
const masterSourceSchema = z.object({
  url: z.url(),
  pages: z.array(z.number().int().positive()),
  checkedAt: z.string(),
  status: z.enum(["verified", "pending"]),
  sha256: z.string(),
});
export const courseMasterSchema = z.object({
  version: z.string(),
  note: z.string(),
  departments: z.record(
    z.string(),
    z.object({ label: z.string(), source: masterSourceSchema }),
  ),
  courses: z.array(
    z.object({
      id: z.string(),
      name: z.string(),
      aliases: z.array(z.string()),
      credits: decimal,
      department: z.string(),
      group: z.enum(["I", "II-a", "II-b", "III", "other"]),
      kind: z.string(),
      year: z.string(),
      term: z.string(),
      page: z.number().int().positive(),
    }),
  ),
});
export type CourseMaster = z.infer<typeof courseMasterSchema>;
export type MasterCourse = CourseMaster["courses"][number];

export function validateCourseMaster(input: unknown): CourseMaster {
  const m = courseMasterSchema.parse(input);
  if (new Set(m.courses.map((x) => x.id)).size !== m.courses.length)
    throw new Error("科目マスターのIDが重複しています");
  if (m.courses.some((x) => !m.departments[x.department]))
    throw new Error("科目マスターに未知の学科");
  return m;
}

// Lookup key: NFKC (Ⅰ→I, fullwidth→ASCII) with all whitespace removed, so
// "Communication Ⅱ" and "CommunicationⅡ" meet. Exact match only, never fuzzy.
export const masterKey = (s: string) => s.normalize("NFKC").replace(/\s+/g, "");
const named = (x: MasterCourse, key: string) =>
  masterKey(x.name) === key || x.aliases.some((a) => masterKey(a) === key);

// Only 第Ⅱ群b and 第Ⅲ群 of another 情報学部 department can enter the 学部枠 (p4 注1).
const FACULTY_QUOTA = new Set(["II-b", "III"]);

// p4 注1: similar courses that may not enter the 学部枠. Stored by name and the
// offering department's label in the curriculum's excludedExternal list.
export function isExcludedSimilar(
  m: CourseMaster,
  c: Curriculum,
  x: MasterCourse,
) {
  return c.excludedExternal.some(
    (e) =>
      masterKey(e.name) === masterKey(x.name) &&
      e.department === m.departments[x.department]?.label,
  );
}

export interface MasterMatch {
  // Set when the lookup settles on one entry (or on equivalent candidates).
  entry?: MasterCourse;
  candidates: MasterCourse[];
  // Candidates differ in a way that matters (credits or 注1 exclusion): the
  // student must pick the offering department.
  needsChoice: boolean;
}

// A course name in the PDF does not say which department offers it. Courses are
// the student's own department's unless listed under the 他学科 heading
// (otherDepartment); only then are the other departments' 第Ⅱ群b/第Ⅲ群 searched.
export function lookupMaster(
  m: CourseMaster,
  c: Curriculum,
  name: string,
  { otherDepartment = false } = {},
): MasterMatch {
  const key = masterKey(name);
  if (!key) return { candidates: [], needsChoice: false };
  const candidates = m.courses.filter(
    (x) =>
      named(x, key) &&
      (otherDepartment
        ? x.department !== c.department && FACULTY_QUOTA.has(x.group)
        : x.department === c.department),
  );
  if (candidates.length <= 1)
    return { entry: candidates[0], candidates, needsChoice: false };
  const [first] = candidates;
  const equivalent = candidates.every(
    (x) =>
      x.credits === first.credits &&
      isExcludedSimilar(m, c, x) === isExcludedSimilar(m, c, first),
  );
  return equivalent
    ? { entry: first, candidates, needsChoice: false }
    : { candidates, needsChoice: true };
}
